# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency contract: hae/evaluation/artifacts.py
# Since it is being implemented in parallel, we assume it exists or implement minimal fallbacks if needed.
# However, the prompt says "Dependency contract: hae/evaluation/artifacts.py (being implemented in parallel...)".
# It implies we should import from it. If it's not present, we might fail.
# But usually in these tasks, if a dependency is specified, we should try to import it.
# If the environment doesn't have it, we might need to stub it or assume it's there.
# Given the strictness, I will try to import it. If it fails, I'll provide a local fallback implementation
# to ensure the harness works even if artifacts.py is missing in the immediate test environment,
# but primarily relying on the contract.

try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback implementation for artifacts.py if not available in the immediate context
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return False
        # Check for markdown decoration or invalid chars
        if '*' in path or '`' in path:
            return True
        if path != path.strip():
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        # Strip markdown decoration
        path = path.replace('*', '').replace('`', '')
        path = path.strip()
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if not is_generated_path(path) and not is_malformed_path(path):
                if any(path.endswith(s) for s in suffixes):
                    count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = len(self.passed_gates)
        return passed / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper()}] {g.name}: {g.detail} ({g.method})")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename/path
    # Common patterns:
    # ```python
    # ```path/to/file.py
    # ```python path/to/file.py
    # ```

    blocks = {}
    # Pattern to match start of code block
    # Group 1: language (optional)
    # Group 2: path/filename (optional)
    pattern = r'```(?:\s*(\w+))?(?:\s+([^\s`]+))?\s*\n(.*?)\n```'

    matches = re.finditer(pattern, text, re.DOTALL)

    for match in matches:
        lang = match.group(1)
        path = match.group(2)
        content = match.group(3)

        # If no path is provided in the fence, we might need to guess or skip.
        # The spec says "path->content map". If no path, we can't map it reliably.
        # However, sometimes the path is inferred from context or just skipped.
        # Let's assume if no path is given, we skip it or use a dummy name?
        # The spec says "Recovers a path->content map". If no path, it's not a map entry.
        if not path:
            continue

        # Sanitize path if needed? The artifacts module handles malformed paths later.
        # We just extract what's there.
        if path in blocks:
            # Append if duplicate? Or overwrite? Usually overwrite or append.
            # Let's append to be safe, or just overwrite.
            blocks[path] += "\n" + content
        else:
            blocks[path] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace_dict'
            elif hasattr(workspace, 'list_files'):
                # Try to get files from workspace object
                try:
                    files = workspace.list_files()
                    if isinstance(files, dict):
                        bundle = files
                    elif isinstance(files, list):
                        # If it returns a list of paths, we need to read them?
                        # But we don't have access to the disk necessarily.
                        # Usually list_files returns a dict of path->content or just paths.
                        # If just paths, we can't verify content easily without disk access.
                        # Let's assume it returns a dict or we fall back.
                        pass
                    source = 'workspace_object'
                except Exception:
                    pass
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace_object'

        # If bundle is empty, try extracting from deliverable_text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable_text'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='packaging_metadata', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No telemetry usage found'),
        ]
        failed_count = sum(1 for g in gates if g.status == FAILED)
        penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=penalty,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle using artifacts logic
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files_count = len(authored_bundle)
        python_files_count = count_source_files(authored_bundle, suffixes=('.py',))

        if authored_files_count == 0:
            return self._create_empty_report(source)

        # Create temp dir
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files_count = len(authored)
        python_files_count = count_source_files(authored, suffixes=('.py',))

        if authored_files_count == 0:
            return self._create_empty_report(source)

        gates = []

        # 1. Syntax Gate
        gates.append(self._check_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._check_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._check_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._check_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._check_telemetry(workdir, authored))

        failed_count = sum(1 for g in gates if g.status == FAILED)
        penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _check_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='No Python files found',
                duration_s=time.time() - start_time
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start_time
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='Syntax errors found: ' + '; '.join(errors),
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast_parse',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _check_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='packaging_metadata',
                detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found',
                duration_s=time.time() - start_time
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            content = authored['pyproject.toml']
            try:
                data = tomllib.loads(content)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='packaging_metadata',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start_time
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='packaging_metadata',
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start_time
                )

        # Try pip install
        # Check if pip is available
        try:
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10)
            pip_available = True
        except Exception:
            pip_available = False

        if not pip_available:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='packaging_metadata',
                detail='pip not available, skipping install check',
                duration_s=time.time() - start_time
            )

        # Run pip install -e . --no-deps --no-build-isolation
        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start_time
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start_time
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start_time
            )

    def _check_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Find non-test authored modules
        # Exclude test files
        non_test_modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # e.g. src/module.py -> module (if src is on path) or src.module
            # We will add workdir and workdir/src to PYTHONPATH
            non_test_modules.append(path)

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No non-test Python modules found',
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if os.name == 'nt':
            python_path = f"{workdir};{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Try to import each module
        import_errors = []
        module_not_found_errors = []

        for path in non_test_modules:
            # Determine module name
            # If path is src/foo.py, module is foo (if src is on path)
            # If path is foo.py, module is foo
            rel_path = path
            if rel_path.startswith('src/'):
                module_name = rel_path[4:-3].replace('/', '.').replace('\\', '.')
            else:
                module_name = rel_path[:-3].replace('/', '.').replace('\\', '.')

            # Skip if it's just __init__.py at root? Or handle it.
            if module_name == '__init__':
                continue

            # Run subprocess to import
            code = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # We need to distinguish.
                        # If the error is "No module named 'foo'" where foo is the module we tried to import, it's a failure.
                        # If it's "No module named 'opentelemetry'", it's skipped.

                        # Simple heuristic: if the module name we tried to import is in the error, it's a failure.
                        # Otherwise, assume it's a dependency issue.
                        if module_name in stderr or f"'{module_name}'" in stderr:
                            import_errors.append(f"{module_name}: {stderr.strip()}")
                        else:
                            module_not_found_errors.append(f"{module_name}: {stderr.strip()}")
                    else:
                        import_errors.append(f"{module_name}: {stderr.strip()}")
            except subprocess.TimeoutExpired:
                import_errors.append(f"{module_name}: Timeout")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        duration = time.time() - start_time

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Import errors: ' + '; '.join(import_errors),
                duration_s=duration,
                evidence={'errors': import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail='Skipped due to missing third-party dependencies: ' + '; '.join(module_not_found_errors),
                duration_s=duration,
                evidence={'skipped': module_not_found_errors}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f"All {len(non_test_modules)} non-test modules imported successfully",
            duration_s=duration
        )

    def _check_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Find test files
        test_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest_run',
                detail='No test files found',
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if os.name == 'nt':
            python_path = f"{workdir};{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Check if pytest is available and functional
        pytest_available = False
        try:
            # Verify pytest can actually run and collect tests in this environment
            # A simple --version check might pass even if collection fails due to missing deps
            # We rely on the execution result to determine if we should fallback.
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10)
            pytest_available = True
        except Exception:
            pytest_available = False

        if pytest_available:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start_time
                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest_run',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if it's a collection error due to missing modules
                    # Pytest exit code 2 is collection error.
                    # If pytest fails to collect or run due to environment issues, we should fallback to stdlib
                    # if the failure is not a genuine test failure.
                    # However, distinguishing 'test failure' from 'environment failure' in pytest is hard.
                    # The hypothesis states: prioritizes pytest even when it fails to initialize.
                    # If pytest returns non-zero, we check if it's a collection error (exit 2) or if it failed to import.
                    # If it's a collection error (exit 2) or import error, we might want to fallback if stdlib can handle it.
                    # But the spec says: 'Use pytest if installed... otherwise run a stdlib fallback'.
                    # The bug is likely that if pytest is installed but fails (e.g. exit 1 due to import error in conftest or similar),
                    # it returns FAILED instead of trying stdlib.
                    # Let's check if the failure looks like an import/collection error that stdlib might handle.
                    # Actually, the simplest fix for 'prioritizes pytest even when it fails to initialize' is to
                    # treat pytest failures that are not 'test failures' (i.e. exit code != 1) as fallback candidates?
                    # No, exit 1 is test failure. Exit 2 is collection error. Exit 3 is internal error.
